/**
 * MSE 微课助手 v1.0.0
 * 适配课程：《农林院校专业学位研究生英语》(courseId=1926)
 *
 * 功能
 *   1. 补满学习时长  —— 直接把每个小节/单元的累计时长推到要求值
 *   2. 自动答必做练习 —— 交空卷建记录 → 取标准答案 → 重新作答 → 提交
 *   3. 只读查看答案  —— 对不可重做的小节，只展示答案不提交
 *   4. 扫描 / 校验   —— 只读统计，不做任何写操作
 *
 * 设计约束
 *   - 只在页面上下文运行（world: MAIN），复用站点自己的 jQuery 与登录态
 *   - 不申请任何权限，不联网到第三方
 *   - 平台版本不匹配时弹警告并降级为只读，不静默失败
 */
(function () {
  'use strict';

  if (window.__MSE_HELPER__) return;
  window.__MSE_HELPER__ = { version: '1.0.0', loadedAt: Date.now() };

  // ============================ 配置 ============================
  const CFG = {
    version: '1.0.0',
    supportedCourseId: '1926',
    supportedCourseName: '农林院校专业学位研究生英语',
    // 适配时平台 JS 的版本特征串，平台改版后这里会失配，触发警告
    expectBaseTokens: ['study-duration-v1-20261008', 'course-progress-v1-20261026'],
    expectSubjectTokens: ['answer-review-v1-20260902'],
    logLimit: 400,
  };

  // ============================ 工具 ============================
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const pad2 = (n) => String(n).padStart(2, '0');
  const fmt = (d) =>
    `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`;
  const clean = (s) =>
    String(s == null ? '' : s).replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

  function ajax(url, data) {
    return new Promise((res, rej) => {
      if (typeof window.$ !== 'function' || !window.$.ajax) {
        return rej(new Error('页面 jQuery 未就绪，请刷新页面'));
      }
      window.$.ajax({
        url, type: 'POST', data, dataType: 'json', timeout: 45000,
        success: res,
        error: (x) => rej(new Error('请求失败 HTTP ' + (x && x.status))),
      });
    });
  }

  // ============================ 环境 ============================
  function readEnv() {
    if (typeof appInfo === 'undefined' || !appInfo || !appInfo.loginUser) return null;
    const course = appInfo.course || {};
    const klass = appInfo.class || {};
    if (!course.Id || !klass.Id) return null;
    return {
      courseId: String(course.Id),
      classId: String(klass.Id),
      courseName: clean(course.Name || ''),
      userId: appInfo.loginUser.Id,
      userName: appInfo.loginUser.RealName || appInfo.loginUser.Name || appInfo.loginUser.LoginName || '',
    };
  }

  function currentSectionId() {
    const box = document.getElementById('studentDetailBox');
    const id = box && box.getAttribute('data-runtime-course-struct-id');
    if (id) return String(id);
    if (typeof gloQs !== 'undefined' && gloQs && gloQs.courseStructId) return String(gloQs.courseStructId);
    return null;
  }

  function scriptVersion(re) {
    const s = [...document.scripts].find((x) => x.src && re.test(x.src));
    if (!s) return null;
    const m = s.src.match(/[?&]v=([^&]+)/);
    return { src: s.src, v: m ? decodeURIComponent(m[1]) : '' };
  }

  // ============================ 版本探测 ============================
  async function probe(env) {
    const out = { ok: true, issues: [], info: {} };

    const base = scriptVersion(/\/Areas\/Base\/Scripts\/customer\/base\.js/i);
    const subj = scriptVersion(/\/Areas\/Adm\/Scripts\/subject\.js/i);
    out.info.baseVer = base ? base.v : '(未找到 base.js)';
    out.info.subjectVer = subj ? subj.v : '(未找到 subject.js)';

    if (!base) {
      out.ok = false;
      out.issues.push('未找到 base.js，页面结构可能已变更');
    } else {
      CFG.expectBaseTokens.forEach((t) => {
        if (!base.v.includes(t)) { out.ok = false; out.issues.push('base.js 缺少特征版本 ' + t); }
      });
    }
    if (!subj) {
      out.ok = false;
      out.issues.push('未找到 subject.js，答题功能不可用');
    } else {
      CFG.expectSubjectTokens.forEach((t) => {
        if (!subj.v.includes(t)) { out.ok = false; out.issues.push('subject.js 缺少特征版本 ' + t); }
      });
    }

    // 课程匹配
    if (env.courseId !== CFG.supportedCourseId) {
      out.ok = false;
      out.issues.push(`当前课程 courseId=${env.courseId}，本插件只适配 ${CFG.supportedCourseId}（${CFG.supportedCourseName}）`);
      out.info.courseMismatch = true;
    }

    // 接口健康检查
    try {
      const tree = await ajax('/Adm/CourseStruct/Tree', { courseId: env.courseId, classId: env.classId });
      if (!Array.isArray(tree)) { out.ok = false; out.issues.push('章节接口返回结构异常（期望数组）'); }
      else out.info.nodeCount = tree.length;
    } catch (e) {
      out.ok = false;
      out.issues.push('章节接口不可用：' + e.message);
    }

    const cur = currentSectionId();
    if (cur) {
      try {
        const sr = await ajax('/Adm/CourseStruct/SubjectReply', { courseStructId: cur, classId: env.classId });
        const okStruct = sr && sr.subjectPager && Array.isArray(sr.subjectPager.SubjectStructs);
        if (!okStruct) { out.ok = false; out.issues.push('题目接口返回结构异常（缺少 subjectPager.SubjectStructs）'); }
      } catch (e) {
        out.ok = false;
        out.issues.push('题目接口不可用：' + e.message);
      }
    }

    return out;
  }

  // ============================ 课程树 ============================
  async function loadTree(env) {
    const tree = await ajax('/Adm/CourseStruct/Tree', { courseId: env.courseId, classId: env.classId });
    if (!Array.isArray(tree)) throw new Error('章节接口返回结构异常');
    return tree;
  }

  function flatten(tree) {
    const out = [];
    (function walk(nodes, path) {
      (nodes || []).forEach((n) => {
        const name = clean(n.text);
        const p = path.concat(name);
        out.push({
          id: String(n.id),
          name,
          path: p.join(' / '),
          req: n.StudyMinutes,
          eff: n.EffectiveStudyMinutes,
          proc: n.StudyProcess,
          isOpen: n.IsOpen,
          must: n.IsMustAnswerSubject,
          subjectCount: Number(n.SubjectCount || 0),
          leaf: !n.children || !n.children.length,
        });
        if (n.children && n.children.length) walk(n.children, p);
      });
    })(tree, []);
    return out;
  }

  const requiredMinutes = (n) => {
    const r = Number(n.eff != null ? n.eff : n.req);
    return isFinite(r) ? r : NaN;
  };

  // ============================ 补学习时长 ============================
  let schoolIdCache = null;

  async function fillOneStudy(env, node, log) {
    const detail = await ajax('/Adm/CourseStruct/StudentDetail', { courseStructId: node.id, classId: env.classId });
    const cs = detail.courseStruct || {};
    const req = Number(cs.EffectiveStudyMinutes != null ? cs.EffectiveStudyMinutes : cs.StudyMinutes);
    if (!isFinite(req) || req <= 0) return { id: node.id, name: node.name, skip: '无时长要求' };
    if (req >= 100000) return { id: node.id, name: node.name, skip: '哨兵值' };

    const target = req * 60;
    const prev = detail.lastLearingLog;
    const cur = prev ? Number(prev.CurTotalSeconds || 0) : 0;
    if (cur >= target) return { id: node.id, name: node.name, skip: '已达标', cur, target };

    const oldSeconds = prev ? Number(prev.Seconds || 0) : 0;
    const newSeconds = oldSeconds + (target - cur);
    const now = new Date();
    const start = new Date(now.getTime() - newSeconds * 1000);

    if (prev && prev.SchoolId) schoolIdCache = prev.SchoolId;
    const schoolId = (prev && prev.SchoolId) || schoolIdCache || 59;

    const payload = {
      UserId: env.userId,
      CourseStructId: Number(node.id),
      ClassId: Number(env.classId),
      SchoolId: schoolId,
      Seconds: newSeconds,
      CurrentNum: (prev && prev.CurrentNum) || 0,
      LastStartTime: fmt(start),
      LastEndTime: fmt(now),
      CurTotalSeconds: cur,
      IsCur: 1,
      CreateTime: (prev && prev.CreateTime) || fmt(start),
      Remark: '',
    };
    if (prev && prev.Id) payload.Id = prev.Id;

    const r = await ajax('/Adm/UserLearingLog/Create', payload);
    const after = (r && r.OtherInfo && r.OtherInfo.UserLearingLog) || {};
    const got = Number(after.CurTotalSeconds || 0);
    return {
      id: node.id, name: node.name, ok: r && r.Type === 'Success',
      from: cur, to: got, target, pct: target ? Math.round((got / target) * 100) : 0,
    };
  }

  async function runFillStudy(env, log, ctx) {
    const tree = await loadTree(env);
    const nodes = flatten(tree).filter((n) => {
      const r = requiredMinutes(n);
      if (!isFinite(r) || r <= 0 || r >= 100000) return false;
      if (n.isOpen === 'no') return false;
      if (n.proc === 100) return false;   // 已完成，省一次详情请求
      return true;
    });
    log(`扫描到 ${nodes.length} 个有时长要求的节点`);
    let done = 0, skipped = 0;
    for (let i = 0; i < nodes.length; i++) {
      if (ctx.stopped) { log('已停止'); break; }
      const n = nodes[i];
      ctx.progress(`补时长 ${i + 1}/${nodes.length}`);
      try {
        const r = await fillOneStudy(env, n, log);
        if (r.skip) { skipped++; }
        else if (r.ok) { done++; log(`  ${n.name}  ${r.from}s → ${r.to}s (${r.pct}%)`); }
        else log(`  失败 ${n.name}`, 'err');
      } catch (e) {
        log(`  异常 ${n.name}：${e.message}`);
      }
      await sleep(120);
    }
    ctx.progress('');
    log(`补时长完成：成功 ${done}，跳过 ${skipped}`);
  }

  // ============================ 必做练习 ============================
  function collectItems(sr) {
    const items = [];
    const walkSub = (s) => {
      (s.Questions || []).forEach((q) => {
        items.push({
          subjectId: String(s.Id),
          questionId: String(q.Id),
          type: q.Type,
          options: Array.isArray(q.Options) ? q.Options : [],
        });
      });
      (s.Children || []).forEach(walkSub);
    };
    const walkStructs = (structs) =>
      (structs || []).forEach((st) => {
        (st.Subjects || []).forEach(walkSub);
        walkStructs(st.children);
      });
    walkStructs(sr.subjectPager && sr.subjectPager.SubjectStructs);
    return items;
  }

  async function fetchAnswers(env, sr, items) {
    const bySubject = {};
    items.forEach((i) => { (bySubject[i.subjectId] = bySubject[i.subjectId] || []).push(i); });
    const param = Object.keys(bySubject).map((sid) => ({
      SubjectId: sid,
      Replys: bySubject[sid].map((i) => ({ questionId: i.questionId, value: '' })),
    }));
    const ca = await ajax('/Adm/Subject/CheckAnswers', {
      param,
      courseId: env.courseId,
      testId: '',
      courseStructHandId: sr.courseStructHand.Id,
    });
    const answers = {};
    (ca || []).forEach((x) => {
      ((x.Subject && x.Subject.Questions) || []).forEach((q) => {
        answers[String(q.Id)] = q.Answer;
      });
    });
    return answers;
  }

  async function solveSection(env, id, log) {
    let sr = await ajax('/Adm/CourseStruct/SubjectReply', { courseStructId: id, classId: env.classId });
    const cs = sr.courseStruct || {};
    const items = collectItems(sr);
    const res = { id: String(id), name: clean(cs.Name).slice(0, 26), questions: items.length, must: cs.IsMustAnswerSubject, repeat: cs.IsAllowedRepeatAnswer };
    if (!items.length) return Object.assign(res, { skip: '无题目' });

    const repeatable = cs.IsAllowedRepeatAnswer == '1';

    // 不可重做且从未提交：只能只读看答案，绝不能交空卷（会永久锁死错误作答）
    if (!sr.courseStructHand && !repeatable) {
      return Object.assign(res, { skip: '未提交且不可重做' });
    }

    let createdEmpty = false;
    if (!sr.courseStructHand) {
      const empty = items.map((i) => ({ SubjectId: i.subjectId, QuestionId: i.questionId, Value: '' }));
      const r0 = await ajax('/Adm/CourseStructReply/SubmitAll', { models: empty, courseStructId: id, classId: env.classId, status: 'Examed' });
      if (!r0 || r0.Type !== 'Success') return Object.assign(res, { err: '建记录失败：' + ((r0 && r0.Content) || '未知') });
      sr = await ajax('/Adm/CourseStruct/SubjectReply', { courseStructId: id, classId: env.classId });
      createdEmpty = true;
    }
    if (!sr.courseStructHand) return Object.assign(res, { err: '未取得提交记录' });

    const answers = await fetchAnswers(env, sr, items);
    res.gotAnswers = Object.keys(answers).length;

    // 不可重做：只回读展示，不写
    if (!repeatable) {
      const reps = sr.courseStructHand.CourseStructReplys || [];
      res.scored = reps.length;
      res.right = reps.filter((x) => Number(x.IsRight) === 1).length;
      res.answersOnly = items.slice(0, 3).map((i) => `${i.type}:${answers[i.questionId]}`);
      return Object.assign(res, { skip: '不可重做，仅展示答案' });
    }

    const del = await ajax('/Adm/CourseStructHand/Delete', { ids: [sr.courseStructHand.Id] });
    if (!del || del.Type !== 'Success') {
      return Object.assign(res, { err: '重做失败：' + ((del && del.Content) || '未知') });
    }

    const models = items.map((i) => {
      const a = answers[i.questionId];
      return { SubjectId: i.subjectId, QuestionId: i.questionId, Value: a != null ? String(a) : '' };
    });
    res.answered = models.filter((m) => m.Value !== '').length;

    const r = await ajax('/Adm/CourseStructReply/SubmitAll', { models, courseStructId: id, classId: env.classId, status: 'Examed' });
    res.ok = r && r.Type === 'Success';
    if (!res.ok) res.err = (r && r.Content) || '提交失败';
    res.createdEmpty = createdEmpty;

    try {
      const after = await ajax('/Adm/CourseStruct/SubjectReply', { courseStructId: id, classId: env.classId });
      const reps = (after.courseStructHand && after.courseStructHand.CourseStructReplys) || [];
      res.scored = reps.length;
      res.right = reps.filter((x) => Number(x.IsRight) === 1).length;
      res.wrong = reps.filter((x) => x.IsRight !== null && x.IsRight !== undefined && Number(x.IsRight) === 0).length;
      res.ungraded = reps.filter((x) => x.IsRight === null || x.IsRight === undefined).length;
    } catch (e) { /* 回读失败不影响 */ }

    return res;
  }

  async function runSolveAll(env, log, ctx) {
    const tree = await loadTree(env);
    const nodes = flatten(tree).filter((n) => {
      if (n.subjectCount <= 0) return false;
      if (n.must == '0') return false;        // 只做必做
      if (n.proc === 100) return false;       // 已完成
      return true;
    });
    log(`待处理必做练习：${nodes.length} 个`);
    if (!nodes.length) { log('没有需要处理的必做练习'); return; }

    let ok = 0, skip = 0, fail = 0;
    for (let i = 0; i < nodes.length; i++) {
      if (ctx.stopped) { log('已停止'); break; }
      const n = nodes[i];
      ctx.progress(`答题 ${i + 1}/${nodes.length}`);
      try {
        const r = await solveSection(env, n.id, log);
        if (r.err) { fail++; log(`  ✗ ${n.name}：${r.err}`); }
        else if (r.skip) { skip++; log(`  - ${n.name}：${r.skip}`); }
        else {
          ok++;
          const judge = r.scored != null ? `对${r.right}/错${r.wrong}/待批${r.ungraded}` : '';
          log(`  ✓ ${n.name}  ${r.answered}/${r.questions} 题  ${judge}`);
        }
      } catch (e) {
        fail++;
        log(`  ✗ ${n.name}：${e.message}`);
      }
      await sleep(200);
    }
    ctx.progress('');
    log(`答题完成：成功 ${ok}，跳过 ${skip}，失败 ${fail}`);
  }

  // ============================ 只读统计 ============================
  async function runScan(env, log, ctx) {
    const tree = await loadTree(env);
    const nodes = flatten(tree).filter((n) => n.subjectCount > 0);
    log(`含练习的小节：${nodes.length}`);
    let mustPending = 0;
    for (const n of nodes) {
      if (ctx.stopped) break;
      try {
        const sr = await ajax('/Adm/CourseStruct/SubjectReply', { courseStructId: n.id, classId: env.classId });
        const items = collectItems(sr);
        const tag = n.must == '1' ? '必做' : '选做';
        const state = sr.courseStructHand ? '已提交' : '未提交';
        const rep = sr.courseStruct.IsAllowedRepeatAnswer == '1' ? '可重做' : '不可重做';
        if (n.must == '1' && n.proc !== 100) mustPending++;
        log(`  [${tag}] ${n.proc}% ${state}/${rep} ${items.length}题  ${n.name}`);
      } catch (e) {
        log(`  ${n.name} 读取失败：${e.message}`);
      }
      await sleep(80);
    }
    log(`扫描完成，必做未完成 ${mustPending} 个`);
  }

  async function runVerify(env, log, ctx) {
    const tree = await loadTree(env);
    const nodes = flatten(tree).filter((n) => n.subjectCount > 0 && n.must != '0');
    let R = 0, W = 0, U = 0, bad = 0;
    log(`校验 ${nodes.length} 个必做小节`);
    for (const n of nodes) {
      if (ctx.stopped) break;
      try {
        const sr = await ajax('/Adm/CourseStruct/SubjectReply', { courseStructId: n.id, classId: env.classId });
        const reps = (sr.courseStructHand && sr.courseStructHand.CourseStructReplys) || [];
        if (!reps.length) { log(`  - ${n.name}：未提交`); continue; }
        const r = reps.filter((x) => Number(x.IsRight) === 1).length;
        const w = reps.filter((x) => x.IsRight !== null && x.IsRight !== undefined && Number(x.IsRight) === 0).length;
        const u = reps.filter((x) => x.IsRight === null || x.IsRight === undefined).length;
        R += r; W += w; U += u;
        if (w > 0) { bad++; log(`  ! ${n.name}：对${r} 错${w} 待批${u}`); }
      } catch (e) { /* ignore */ }
      await sleep(60);
    }
    log(`合计：客观题对 ${R}，错 ${W}，主观题待批 ${U}`);
    if (bad) log(`有 ${bad} 个小节存在错题，请查看上方明细`);
    else log('没有发现错题');
  }

  // ============================ UI ============================
  const BG = 'data:image/jpeg;base64,';

  const CSS = `
  :host { all: initial; }
  .wrap {
    position: fixed; right: 18px; bottom: 18px; width: 440px; z-index: 2147483000;
    font: 13.5px/1.6 -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
    color: #1f2328; background: #fff url("${BG}") center 26%/cover no-repeat;
    border: 1px solid #d8dee4; border-radius: 14px;
    box-shadow: 0 14px 38px rgba(15,23,42,.22); overflow: hidden;
  }
  .hdr {
    position: relative; min-height: 96px; box-sizing: border-box;
    padding: 8px 13px 12px;
    display: flex; flex-direction: column; justify-content: flex-end; gap: 3px;
    border-bottom: 1px solid rgba(15,23,42,.2);
  }
  .hdr::before {
    content: ''; position: absolute; inset: 0;
    background: linear-gradient(180deg, rgba(10,15,28,.42) 0%, rgba(10,15,28,.72) 45%, rgba(10,15,28,.93) 100%);
  }
  .hdr > * { position: relative; }
  .hdr .bar { display: flex; align-items: center; justify-content: flex-end; gap: 8px; height: 18px; }
  .hdr .t {
    font-weight: 800; font-size: 16px; color: #fff; line-height: 1.25; letter-spacing: .3px;
    text-shadow: 0 1px 5px rgba(0,0,0,.95), 0 0 14px rgba(0,0,0,.55);
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  .hdr .v { color: rgba(255,255,255,.85); font-size: 11px; text-shadow: 0 1px 3px rgba(0,0,0,.7); }
  .hdr button {
    border: 0; background: rgba(255,255,255,.16); color: #fff; cursor: pointer;
    font-size: 14px; line-height: 1; padding: 3px 7px; border-radius: 6px;
    text-shadow: 0 1px 3px rgba(0,0,0,.6);
  }
  .hdr button:hover { background: rgba(255,255,255,.3); color: #fff; }
  .bd { padding: 12px 14px 14px; background: rgba(255,255,255,.92); }
  .bd.min { display: none; }
  .banner {
    display: none; margin-bottom: 9px; padding: 8px 10px; border-radius: 8px;
    background: #fff4f4; border: 1px solid #ffd0d0; color: #a4262c; font-size: 12px;
  }
  .banner.show { display: block; }
  .banner b { display: block; margin-bottom: 3px; }
  .banner .hint { color: #8a3a3f; font-size: 11px; margin-top: 4px; }
  .status { font-size: 12px; color: #57606a; margin-bottom: 8px; min-height: 17px; }
  .status .dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: #2da44e; margin-right: 5px; vertical-align: 1px; }
  .status.warn .dot { background: #bf8700; }
  .status.err .dot { background: #cf222e; }
  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-bottom: 8px; }
  .grid.three { grid-template-columns: 1fr 1fr 1fr; }
  button.act {
    border: 1px solid #d0d7de; background: #f6f8fa; color: #1f2328; border-radius: 8px;
    padding: 8px 6px; font-size: 12.5px; cursor: pointer; font-family: inherit;
  }
  button.act:hover:not(:disabled) { background: #eef2f6; border-color: #b9c2cc; }
  button.act:disabled { opacity: .45; cursor: not-allowed; }
  button.act.primary { background: #1f6feb; border-color: #1f6feb; color: #fff; }
  button.act.primary:hover:not(:disabled) { background: #1a5fd0; }
  button.act.danger { color: #cf222e; border-color: #f0c4c7; background: #fff5f5; }
  .log {
    height: 236px; overflow: auto; background: rgba(15,23,42,.96); color: #cbd5e1; border-radius: 9px;
    padding: 9px 10px; font: 12px/1.55 Consolas, "Courier New", monospace; white-space: pre-wrap;
    word-break: break-all;
  }
  .log .ok { color: #7ee787; }
  .log .warn { color: #f0b849; }
  .log .err { color: #ff7b72; }
  .log .dim { color: #7d8590; }
  .foot { margin-top: 7px; font-size: 11px; color: #8a94a0; display: flex; justify-content: space-between; }
  `;

  const HTML = `
  <div class="wrap">
    <div class="hdr">
      <div class="bar">
        <span class="v">v${CFG.version}</span>
        <button data-act="min" title="折叠">—</button>
      </div>
      <div class="t">MSE-加速英语老师的消化系统！</div>
    </div>
    <div class="bd">
      <div class="banner" id="banner"></div>
      <div class="status" id="status"><span class="dot"></span><span id="statusText">正在检测环境…</span></div>
      <div class="grid">
        <button class="act primary" data-act="study">补满学习时长</button>
        <button class="act primary" data-act="answer">自动答必做练习</button>
      </div>
      <div class="grid three">
        <button class="act" data-act="auto">一键全自动</button>
        <button class="act" data-act="scan">扫描</button>
        <button class="act" data-act="verify">校验</button>
      </div>
      <div class="grid">
        <button class="act danger" data-act="stop">停止当前任务</button>
        <button class="act" data-act="clear">清空日志</button>
      </div>
      <div class="log" id="log"></div>
      <div class="foot"><span id="footLeft">就绪</span><span>仅适配本课程</span></div>
    </div>
  </div>
  `;

  let root, el = {}, busy = false;
  const ctx = { stopped: false, progress: (t) => { el.footLeft && (el.footLeft.textContent = t || '就绪'); } };

  function log(msg, cls) {
    if (!el.log) return;
    const line = document.createElement('div');
    if (cls) line.className = cls;
    line.textContent = `[${new Date().toLocaleTimeString()}] ${msg}`;
    el.log.appendChild(line);
    while (el.log.childNodes.length > CFG.logLimit) el.log.removeChild(el.log.firstChild);
    el.log.scrollTop = el.log.scrollHeight;
  }

  function setStatus(text, kind) {
    if (!el.status) return;
    el.status.className = 'status' + (kind ? ' ' + kind : '');
    el.statusText.textContent = text;
  }

  function showBanner(title, lines) {
    if (!el.banner) return;
    el.banner.innerHTML = '';
    const b = document.createElement('b');
    b.textContent = title;
    el.banner.appendChild(b);
    lines.forEach((t) => {
      const d = document.createElement('div');
      d.textContent = t;
      el.banner.appendChild(d);
    });
    const hint = document.createElement('div');
    hint.className = 'hint';
    hint.textContent = '建议联系作者更新适配（把上方版本信息一起发过去），或等待维护后再使用。';
    el.banner.appendChild(hint);
    el.banner.classList.add('show');
  }

  function setBusy(v, label) {
    busy = v;
    ['study', 'answer', 'auto', 'scan', 'verify'].forEach((a) => {
      const b = root.querySelector(`[data-act="${a}"]`);
      if (b) b.disabled = v;
    });
    if (v) setStatus(label || '执行中…', 'warn');
  }

  function mount() {
    const host = document.createElement('div');
    host.id = '__mse_helper_host__';
    host.style.cssText = 'all:initial;position:fixed;inset:auto 0 0 auto;width:0;height:0;z-index:2147483000;';
    const shadow = host.attachShadow({ mode: 'open' });
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(CSS);
      shadow.adoptedStyleSheets = [sheet];
    } catch (e) {
      const st = document.createElement('style');
      st.textContent = CSS;
      shadow.appendChild(st);
    }
    const box = document.createElement('div');
    box.innerHTML = HTML;
    shadow.appendChild(box);
    document.documentElement.appendChild(host);

    root = shadow;
    el = {
      banner: shadow.getElementById('banner'),
      status: shadow.getElementById('status'),
      statusText: shadow.getElementById('statusText'),
      log: shadow.getElementById('log'),
      footLeft: shadow.getElementById('footLeft'),
    };

    shadow.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-act]');
      if (!btn) return;
      const act = btn.getAttribute('data-act');
      if (act === 'min') {
        const bd = shadow.querySelector('.bd');
        bd.classList.toggle('min');
        btn.textContent = bd.classList.contains('min') ? '+' : '—';
        return;
      }
      if (act === 'clear') { el.log.innerHTML = ''; return; }
      if (act === 'stop') { ctx.stopped = true; log('已请求停止，等待当前步骤结束…', 'warn'); return; }
      if (busy) { log('有任务正在执行，请先停止', 'warn'); return; }
      handle(act);
    });
  }

  async function handle(act) {
    const env = readEnv();
    if (!env) { setStatus('未登录或不在课程学习页', 'err'); log('未检测到登录信息，请进入课程学习页后重试', 'err'); return; }

    ctx.stopped = false;
    setBusy(true, '准备中…');
    try {
      if (act === 'study') {
        log('开始补学习时长…');
        await runFillStudy(env, log, ctx);
      } else if (act === 'answer') {
        log('开始自动答必做练习…');
        await runSolveAll(env, log, ctx);
      } else if (act === 'auto') {
        log('一键全自动：先补时长，再答必做练习');
        await runFillStudy(env, log, ctx);
        if (!ctx.stopped) await runSolveAll(env, log, ctx);
      } else if (act === 'scan') {
        await runScan(env, log, ctx);
      } else if (act === 'verify') {
        await runVerify(env, log, ctx);
      }
      setStatus('完成', 'ok');
    } catch (e) {
      setStatus('执行出错：' + e.message, 'err');
      log('出错：' + e.message, 'err');
    } finally {
      setBusy(false);
      ctx.progress('');
    }
  }

  // ============================ 启动 ============================
  async function boot() {
    mount();
    log('插件已加载 v' + CFG.version, 'dim');

    // 等待页面框架就绪
    for (let i = 0; i < 40; i++) {
      if (typeof window.$ === 'function' && typeof appInfo !== 'undefined' && appInfo && appInfo.loginUser) break;
      await sleep(250);
    }

    const env = readEnv();
    if (!env) {
      setStatus('未登录或不在课程学习页', 'err');
      log('未检测到登录信息。请登录后进入课程学习页。', 'err');
      return;
    }

    log(`账号 ${env.userName || env.userId}｜课程 ${env.courseName || env.courseId}｜班级 ${env.classId}`, 'dim');

    setStatus('正在检测平台版本…', 'warn');
    const p = await probe(env);
    log('平台 base.js：' + p.info.baseVer.slice(0, 120), 'dim');
    log('平台 subject.js：' + p.info.subjectVer.slice(0, 120), 'dim');

    if (p.ok) {
      setStatus('环境正常，可以使用', 'ok');
      log('版本探测通过', 'ok');
    } else {
      setStatus('平台已变更，功能可能失效', 'err');
      showBanner('检测到平台更新，部分功能不可用', p.issues);
      p.issues.forEach((t) => log('! ' + t, 'err'));
      // 降级：禁用写操作，保留扫描
      ['study', 'answer', 'auto'].forEach((a) => {
        const b = root.querySelector(`[data-act="${a}"]`);
        if (b) { b.disabled = true; b.title = '平台版本不匹配，已禁用'; }
      });
    }
  }

  boot();
})();
